{"content": "/**
 * Event manager page for viewing and managing scheduled events.
 */
import { useState } from 'react';
import { format } from 'date-fns';
import { Plus, Trash2, Eye } from 'lucide-react';
import { 
  Card, 
  CardContent, 
  CardHeader, 
  CardTitle 
} from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  Tabs, 
  TabsContent, 
  TabsList, 
  TabsTrigger 
} from '@/components/ui/tabs';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import { ScrollArea } from '@/components/ui/scroll-area';
import { useEvents, useCancelEvent, type SimulatorEvent, type EventStatus } from '@/api';

const statusColors: Record<EventStatus, string> = {
  pending: 'bg-yellow-500',
  executed: 'bg-green-500',
  cancelled: 'bg-gray-500',
  failed: 'bg-red-500',
};

function EventCard({ event }: { event: SimulatorEvent }) {
  const cancelEvent = useCancelEvent();
  const [showDetails, setShowDetails] = useState(false);

  const handleCancel = () => {
    if (window.confirm('Cancel this event?')) {
      cancelEvent.mutate(event.id);
    }
  };

  return (
    <Card>
      <CardContent className="p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className={`w-2 h-2 rounded-full ${statusColors[event.status]}`} />
            <div>
              <p className="font-medium capitalize">{event.modality}</p>
              <p className="text-sm text-muted-foreground">
                {format(new Date(event.scheduled_time), 'yyyy-MM-dd HH:mm:ss')}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Badge variant="outline">{event.status}</Badge>
            <Dialog open={showDetails} onOpenChange={setShowDetails}>
              <DialogTrigger asChild>
                <Button variant="ghost" size="icon">
                  <Eye className="h-4 w-4" />
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl">
                <DialogHeader>
                  <DialogTitle>Event Details</DialogTitle>
                </DialogHeader>
                <ScrollArea className="max-h-96">
                  <pre className="text-sm bg-muted p-4 rounded-md overflow-auto">
                    {JSON.stringify(event, null, 2)}
                  </pre>
                </ScrollArea>
              </DialogContent>
            </Dialog>
            {event.status === 'pending' && (
              <Button
                variant="ghost"
                size="icon"
                onClick={handleCancel}
                disabled={cancelEvent.isPending}
              >
                <Trash2 className="h-4 w-4 text-destructive" />
              </Button>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

export function EventManager() {
  const [statusFilter, setStatusFilter] = useState<EventStatus | 'all'>('all');

  const { data: eventsData, isLoading } = useEvents(
    statusFilter === 'all' ? undefined : { status: statusFilter }
  );

  const events = eventsData?.events || [];

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Event Manager</h2>
          <p className="text-muted-foreground">
            View and manage scheduled simulation events
          </p>
        </div>
        <Button disabled>
          <Plus className="mr-2 h-4 w-4" />
          Create Event
        </Button>
      </div>

      <Tabs value={statusFilter} onValueChange={(v) => setStatusFilter(v as EventStatus | 'all')}>
        <TabsList>
          <TabsTrigger value="all">All</TabsTrigger>
          <TabsTrigger value="pending">Pending</TabsTrigger>
          <TabsTrigger value="executed">Executed</TabsTrigger>
          <TabsTrigger value="cancelled">Cancelled</TabsTrigger>
          <TabsTrigger value="failed">Failed</TabsTrigger>
        </TabsList>

        <TabsContent value={statusFilter} className="mt-4">
          {isLoading ? (
            <div className="space-y-2">
              {[...Array(5)].map((_, i) => (
                <Card key={i} className="animate-pulse">
                  <CardContent className="p-4">
                    <div className="h-12 bg-muted rounded" />
                  </CardContent>
                </Card>
              ))}
            </div>
          ) : events.length === 0 ? (
            <Card>
              <CardHeader>
                <CardTitle className="text-center text-muted-foreground">
                  No events found
                </CardTitle>
              </CardHeader>
            </Card>
          ) : (
            <div className="space-y-2">
              {events.map((event) => (
                <EventCard key={event.id} event={event} />
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}
