// ============================================================================
// Simulation Types
// ============================================================================

export interface SimulationStatus {
  is_running: boolean;
  current_time: string;
  is_paused: boolean;
  auto_advance: boolean;
  time_scale: number;
  pending_events: number;
  executed_events: number;
  failed_events: number;
  next_event_time: string | null;
}

export interface StartSimulationRequest {
  auto_advance?: boolean;
  time_scale?: number;
}

export interface UndoRedoRequest {
  count?: number;
}

export interface ClearRequest {
  reset_time_to?: string;
}

// ============================================================================
// Time Types
// ============================================================================

export interface TimeState {
  current_time: string; // ISO datetime string
  time_scale: number;
  is_paused: boolean;
  auto_advance: boolean;
  mode: 'manual' | 'auto' | 'paused';
}

export interface AdvanceTimeRequest {
  seconds: number;
}

export interface SetTimeRequest {
  target_time: string; // ISO datetime string
}

export interface SetScaleRequest {
  time_scale: number;
}

/**
 * Simulation status indicator with statistics.
 */
import { Activity, CheckCircle, Clock, XCircle } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { useSimulationStatus } from '@/api';

export function SimulationStatus() {
  const { data: status, isLoading, isError } = useSimulationStatus();

  if (isLoading) {
    return (
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-sm font-medium">Simulation Status</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="animate-pulse text-muted-foreground">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  if (isError || !status) {
    return (
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-sm font-medium">Simulation Status</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-destructive">Failed to load status</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-sm font-medium flex items-center gap-2">
          <Activity className="h-4 w-4" />
          Simulation Status
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-2">
        <div className="grid grid-cols-2 gap-4 text-sm">
          <div className="flex items-center gap-2">
            <Clock className="h-4 w-4 text-muted-foreground" />
            <span className="text-muted-foreground">Pending:</span>
            <span className="font-medium">{status.pending_events}</span>
          </div>
          <div className="flex items-center gap-2">
            <CheckCircle className="h-4 w-4 text-green-500" />
            <span className="text-muted-foreground">Executed:</span>
            <span className="font-medium">{status.executed_events}</span>
          </div>
          <div className="flex items-center gap-2">
            <XCircle className="h-4 w-4 text-red-500" />
            <span className="text-muted-foreground">Failed:</span>
            <span className="font-medium">{status.failed_events}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-muted-foreground">Mode:</span>
            <span className="font-medium capitalize">
              {status.is_paused ? 'Paused' : status.auto_advance ? 'Auto' : 'Manual'}
            </span>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * Main application header with simulation status and global controls.
 */
import { Play, Pause, Square, RotateCcw, Undo, Redo } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { 
  useSimulationStatus, 
  useStartSimulation, 
  useStopSimulation,
  useUndo,
  useRedo 
} from '@/api';
import { usePauseTime, useResumeTime } from '@/api';
import { TimeDisplay } from '@/components/simulation/TimeDisplay';

export function Header() {
  const { data: status } = useSimulationStatus();
  const startSimulation = useStartSimulation();
  const stopSimulation = useStopSimulation();
  const pauseTime = usePauseTime();
  const resumeTime = useResumeTime();
  const undo = useUndo();
  const redo = useRedo();

  const isRunning = status?.is_running ?? false;
  const isPaused = status?.is_paused ?? false;

  const handlePlayPause = () => {
    if (!isRunning) {
      startSimulation.mutate({});
    } else if (isPaused) {
      resumeTime.mutate();
    } else {
      pauseTime.mutate();
    }
  };

  const handleStop = () => {
    stopSimulation.mutate();
  };

  return (
    <header className="border-b bg-background px-4 py-2">
      <div className="flex items-center justify-between">
        {/* Left: Title and Status */}
        <div className="flex items-center gap-4">
          <h1 className="text-xl font-bold">UES Control Panel</h1>
          <Badge variant={isRunning ? (isPaused ? 'secondary' : 'default') : 'outline'}>
            {isRunning ? (isPaused ? 'Paused' : 'Running') : 'Stopped'}
          </Badge>
        </div>

        {/* Center: Time Display */}
        <div className="flex items-center gap-2">
          <TimeDisplay />
        </div>

        {/* Right: Controls */}
        <div className="flex items-center gap-2">
          {/* Undo/Redo */}
          <Button
            variant="outline"
            size="icon"
            onClick={() => undo.mutate({})}
            title="Undo"
          >
            <Undo className="h-4 w-4" />
          </Button>
          <Button
            variant="outline"
            size="icon"
            onClick={() => redo.mutate({})}
            title="Redo"
          >
            <Redo className="h-4 w-4" />
          </Button>

          <Separator orientation="vertical" className="h-6" />

          {/* Simulation Controls */}
          <Button
            variant={isRunning && !isPaused ? 'secondary' : 'default'}
            size="icon"
            onClick={handlePlayPause}
            title={isRunning && !isPaused ? 'Pause' : 'Play'}
          >
            {isRunning && !isPaused ? (
              <Pause className="h-4 w-4" />
            ) : (
              <Play className="h-4 w-4" />
            )}
          </Button>
          <Button
            variant="outline"
            size="icon"
            onClick={handleStop}
            disabled={!isRunning}
            title="Stop"
          >
            <Square className="h-4 w-4" />
          </Button>
          <Button
            variant="outline"
            size="icon"
            onClick={() => window.confirm('Reset simulation?') && stopSimulation.mutate()}
            title="Reset"
          >
            <RotateCcw className="h-4 w-4" />
          </Button>
        </div>
      </div>
    </header>
  );
}

/**
 * Time advancement controls (advance by duration, skip to next event).
 */
import { useState } from 'react';
import { FastForward, SkipForward } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useAdvanceTime, useSkipToNext } from '@/api';

export function TimeAdvanceControls() {
  const [minutes, setMinutes] = useState('5');
  const advanceTime = useAdvanceTime();
  const skipToNext = useSkipToNext();

  const handleAdvance = () => {
    const mins = parseInt(minutes, 10);
    if (!isNaN(mins) && mins > 0) {
      // Convert minutes to seconds as the API expects seconds
      advanceTime.mutate({ seconds: mins * 60 });
    }
  };

  const handleSkipToNext = () => {
    skipToNext.mutate();
  };

  return (
    <div className="space-y-3">
      <span className="text-sm font-medium">Time Advance</span>

      <div className="flex gap-2">
        <Input
          type="number"
          value={minutes}
          onChange={(e) => setMinutes(e.target.value)}
          placeholder="Minutes"
          min="1"
          className="w-24"
        />
        <Button
          variant="outline"
          onClick={handleAdvance}
          disabled={advanceTime.isPending}
        >
          <FastForward className="mr-2 h-4 w-4" />
          Advance
        </Button>
      </div>

      <Button
        variant="outline"
        onClick={handleSkipToNext}
        disabled={skipToNext.isPending}
        className="w-full"
      >
        <SkipForward className="mr-2 h-4 w-4" />
        Skip to Next Event
      </Button>
    </div>
  );
}

